# Verify concise rules on the fully provided demos; simulate horizontal/vertical rays and target-bar halos.
def transform(g, srcs, rails, axis):
 o=[r[:] for r in g]; R=len(o); C=len(o[0])
 for r,c in srcs:
  if axis=='h':
   for j in range(C):
    if o[r][j]==0:o[r][j]=1
   for cc in rails:
    if cc==c:continue
    for rr in range(max(0,r-1),min(R,r+2)):
     for j in range(max(0,cc-1),min(C,cc+2)):
      if (rr,j)!=(r,cc) and o[rr][j]!=3:o[rr][j]=1
  else:
   for i in range(R):
    if o[i][c]==0:o[i][c]=1
   for rr in rails:
    if rr==r:continue
    for i in range(max(0,rr-1),min(R,rr+2)):
     for j in range(max(0,c-1),min(C,c+2)):
      if (i,j)!=(rr,c) and o[i][j]!=3:o[i][j]=1
 return o
